import org.springframework.web.client.RestClient;

class HttpPaymentGatewayTest {

    private HttpServer provider;
    private final AtomicReference<String> method = new AtomicReference<>();
    private final AtomicReference<String> path = new AtomicReference<>();
    private final AtomicReference<String> contentType = new AtomicReference<>();
    private final AtomicReference<String> body = new AtomicReference<>();
    private volatile int status;
    private volatile String responseBody;

    @BeforeEach
    void startProvider() throws Exception {
        provider = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
        provider.createContext("/", exchange -> {
            method.set(exchange.getRequestMethod());
            path.set(exchange.getRequestURI().getPath());
            contentType.set(exchange.getRequestHeaders().getFirst("Content-Type"));
            body.set(new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
            var bytes = responseBody.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().add("Content-Type", "application/json");
            exchange.sendResponseHeaders(status, bytes.length == 0 ? -1 : bytes.length);
            if (bytes.length > 0) exchange.getResponseBody().write(bytes);
            exchange.close();
        });
        provider.start();
    }

    @AfterEach
    void stopProvider() {
        provider.stop(0);
    }

    private HttpPaymentGateway gateway() {
        var url = "http://localhost:" + provider.getAddress().getPort();
        return new HttpPaymentGateway(RestClient.builder().baseUrl(url).build());
    }

    private AuthorizationOutcome authorize(int status, String responseBody) {
        this.status = status;
        this.responseBody = responseBody;
        return gateway().authorize("ORD-7", new Money(new BigDecimal("12.50"), "eur"));
    }

    @Test
    void the_authorization_is_posted_as_json_with_reference_amount_and_currency() {
        authorize(200, "{\"status\":\"approved\"}");

        assertThat(method.get()).isEqualTo("POST");
        assertThat(path.get()).isEqualTo("/v1/authorizations");
        assertThat(contentType.get()).startsWith("application/json");
        assertThat(body.get()).isEqualTo("{\"reference\":\"ORD-7\",\"amount\":12.50,\"currency\":\"EUR\"}");
    }

    @Test
    void an_approved_answer_is_read_as_approved() {
        assertThat(authorize(200, "{\"status\":\"approved\"}")).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_answer_is_read_as_declined() {
        assertThat(authorize(200, "{\"status\":\"declined\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void additional_fields_in_the_answer_are_tolerated() {
        assertThat(authorize(200, "{\"status\":\"approved\",\"id\":\"a-1\",\"risk\":{\"score\":3}}"))
                .isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void an_unknown_status_is_never_treated_as_approved() {
        assertThat(authorize(200, "{\"status\":\"pending\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_answer_without_status_is_never_treated_as_approved() {
        assertThat(authorize(200, "{}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_refusal_with_402_is_a_declined_outcome() {
        assertThat(authorize(402, "{\"error\":\"insufficient_funds\"}")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_402_refusal_without_a_body_is_a_declined_outcome() {
        assertThat(authorize(402, "")).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void a_request_the_provider_rejects_is_reported_as_a_failure() {
        assertThatThrownBy(() -> authorize(400, "{\"error\":\"bad_request\"}"))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("400");
    }

    @Test
    void a_provider_outage_is_reported_as_a_failure_not_a_decline() {
        assertThatThrownBy(() -> authorize(503, "{}"))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("503");
    }
}
